const defaults={user:{name:'Aarav Mehta',email:'aarav@example.com',journey:''},saved:[],compare:[],evaluations:[],recent:[],activities:[],notifications:true,estimator:{mode:'setup',category:'Cafe',city:'Jaipur',size:'Medium',area:1000,rent:75000,employees:8,equipment:450000,inventory:240000,interior:650000,licences:65000,marketing:80000,months:4},acq:{price:3200000,inventory:185000,liabilities:0,upgrade:160000,months:3},equipment:[...DATA.equipment],customBusinesses:[],seenOnboarding:false};
let state=loadState(),page='dashboard',marketFilters={search:'',city:'All cities',category:'All categories',budget:Infinity,sort:'Recommended'},selectedBusiness=null,scenario='realistic',advisorMessages=[{role:'assistant',text:'Hello Aarav. I can help you explore acquisition options, estimate setup costs, or pressure-test a business using the illustrative data in this workspace. What are you considering?'}],estimateView='new',equipmentModal=false;
function loadState(){try{return {...structuredClone(defaults),...JSON.parse(localStorage.getItem('enterprisex-v1')||'{}')}}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem('enterprisex-v1',JSON.stringify(state))}
function ensureEquipmentMetadata(){const installed=['2022-03-14','2021-11-08','2023-06-22','2024-01-19'];let changed=false;state.equipment.forEach((e,i)=>{if(!e.installed){e.installed=installed[i]||new Date().toISOString().slice(0,10);changed=true}if(!Array.isArray(e.maintenanceHistory)){e.maintenanceHistory=[{date:e.last||'2026-01-01',event:'Preventive service recorded'}];changed=true}});if(changed)save()}
ensureEquipmentMetadata();
const money=(n,compact=false)=>{n=Number(n)||0;return compact&&Math.abs(n)>=100000?`₹${(n/100000).toFixed(1)}L`:`₹${Math.round(n).toLocaleString('en-IN')}`},num=(n)=>Number(n)||0,esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allBusinesses=()=>[...DATA.businesses,...state.customBusinesses],findBiz=id=>allBusinesses().find(b=>b.id===id),profit=b=>b.revenue-b.expenses,roi=b=>profit(b)*12/b.price*100;
function activity(text){state.activities.unshift({text,date:new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short'})});state.activities=state.activities.slice(0,12);save()}
const navGroups=[['OVERVIEW',[['dashboard','◫','Overview']]],['FUNDING & FINANCING',[['matching','⌘','Funding match']]],['WORKSPACE',[['marketplace','⌕','Marketplace'],['estimator','◉','Cost estimator'],['digital-twin','⤢','Digital twin'],['financial-studio','▥','Financial studio']]],['INTELLIGENCE',[['maintenance','⚙','Maintenance'],['risk','⛨','Risk assessment'],['due-diligence','☷','Due diligence'],['locations','◎','Locations'],['advisor','✳','AI advisor']]],['PLANNING',[['compare','⇄','Startup vs acquire'],['reports','▤','Reports']]],['ACCOUNT',[['settings','⚙','Settings']]]];
const pageNames=Object.fromEntries(navGroups.flatMap(g=>g[1]).map(x=>[x[0],x[2]]));
function navMarkup(){return navGroups.map(([label,items])=>`<div class="nav-label">${label}</div><div class="nav">${items.map(([id,icon,name])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="nav-icon">${icon}</span>${name}</button>`).join('')}</div>`).join('')}
function frame(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><span class="brandmark">X</span><span>EnterpriseX<small>BUSINESS INTELLIGENCE</small></span></a>${navMarkup()}<div class="side-bottom"><div class="demo-card"><strong><i class="demo-dot"></i> DEMO ENVIRONMENT</strong><p>All marketplace, sensor and market figures are illustrative sample data.</p></div><div class="user-row"><div class="avatar">${esc((state.user.name||'A M').split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div style="flex:1"><strong>${esc(state.user.name||'Demo user')}</strong><small>Workspace owner</small></div><button class="icon-btn" data-page="settings" title="Settings">⋯</button></div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" id="menu-toggle">☰</button><span class="crumb">Workspace <span style="color:#586778">/</span> ${pageNames[page]||'Overview'}</span></div><div class="top-actions"><input class="search-global" id="global-search" placeholder="⌕  Search businesses, tools…"/><button class="icon-btn" id="notifications" title="Notifications">♧<i class="notif-dot"></i></button><div class="avatar hide-mobile">${esc((state.user.name||'AM').split(' ').map(x=>x[0]).slice(0,2).join(''))}</div></div></header><section class="content" id="content"></section></main><nav class="mobile-nav">${[['dashboard','◫','Home'],['marketplace','⌕','Explore'],['estimator','◉','Estimate'],['maintenance','⚙','Assets'],['settings','☻','Profile']].map(([id,i,n])=>`<button data-page="${id}" class="${page===id?'active':''}"><span>${i}</span>${n}</button>`).join('')}</nav></div><div id="overlay"></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));document.getElementById('menu-toggle').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('global-search').onkeydown=e=>{if(e.key==='Enter'){page='marketplace';marketFilters.search=e.target.value;render()}};document.getElementById('notifications').onclick=()=>notify(state.activities.length?`${state.activities.length} recent activity item(s).`:'You are all caught up.');renderPage()}
function go(p){page=p;history.replaceState(null,'','#'+p);document.getElementById('sidebar')?.classList.remove('open');frame()}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">EnterpriseX workspace</div><h1>${title}</h1><p>${sub}</p></div><div class="header-actions">${actions}</div></div>`}
function cardTitle(title,sub='',right=''){return `<div class="section-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function chartSvg(a,b,labels=DATA.months,unit=null){unit=unit||(labels===DATA.months?'₹L':Math.max(...a)>20?'°C':' mm/s');const max=Math.max(...a,...(b||[]))*1.2,w=600,h=160;const pts=arr=>arr.map((v,i)=>`${35+i*(w-60)/(arr.length-1)},${h-20-v/max*(h-43)}`).join(' ');let ticks=[0,.33,.66,1].map(f=>{let y=h-20-f*(h-43),v=max*f,label=unit==='₹L'?`₹${v.toFixed(0)}L`:`${v.toFixed(0)}${unit}`;return `<line class="gridline" x1="35" x2="${w}" y1="${y}" y2="${y}"/><text class="axis-label" x="2" y="${y+3}">${label}</text>`}).join('');return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${ticks}<defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#62d0d2"/><stop offset="1" stop-color="#62d0d2" stop-opacity="0"/></linearGradient></defs><polygon class="area-a" points="35,${h-20} ${pts(a)} ${w},${h-20}"/><polyline class="line-a" points="${pts(a)}"/>${b?`<polyline class="line-b" points="${pts(b)}"/>`:''}${labels.map((l,i)=>`<text class="axis-label" text-anchor="middle" x="${35+i*(w-60)/(labels.length-1)}" y="${h-2}">${l}</text>`).join('')}</svg></div>`}
function bars(values,labels){let max=Math.max(...values)*1.18;return `<div class="chart-wrap"><svg viewBox="0 0 600 160" preserveAspectRatio="none">${[0,.5,1].map(f=>`<line class="gridline" x1="32" x2="600" y1="${130-f*105}" y2="${130-f*105}"/>`).join('')}${values.map((v,i)=>{let x=53+i*88,ht=v/max*100;return `<rect x="${x}" y="${130-ht}" width="32" height="${ht}" rx="4" class="bar" opacity="${.64+i*.05}"/><text class="axis-label" text-anchor="middle" x="${x+16}" y="151">${labels[i]}</text>`}).join('')}</svg></div>`}
function dashboard(){let bs=allBusinesses(),inv=bs.reduce((a,b)=>a+b.price,0),avg=Math.round(bs.reduce((a,b)=>a+b.health,0)/bs.length),saved=state.saved.map(findBiz).filter(Boolean),risk=state.equipment.filter(e=>e.health<70).length;let insights=[`${bs.filter(b=>b.price<=5000000).length} sample acquisition opportunities are priced below ₹50L.`,`${saved[0]?`${saved[0].name} is saved for your review.`:'Save an opportunity to build your shortlist.'}`,`${risk?`${risk} monitored asset${risk>1?'s':''} currently meet the maintenance alert rules.`:'No equipment is currently in the high urgency band.'}`];return `${head('Good evening, '+esc((state.user.name||'there').split(' ')[0])+'.','Your business decisions, grounded in intelligence.','<button class="btn" data-page="reports">Export report</button><button class="btn primary" data-page="marketplace">Explore opportunities ↗</button>')}${!state.seenOnboarding?`<div class="card" style="margin-bottom:14px;border-color:#31515a;background:#14252d">${cardTitle('Set your workspace direction','Choose a journey to personalize your dashboard')}<div class="row" style="flex-wrap:wrap">${[['Start a business','New setup cost planning'],['Acquire a business','Compare current listings'],['Evaluate a business','Due diligence and risk'],['Monitor operations','Equipment and maintenance']].map(([x,y])=>`<button class="btn" data-journey="${x}">${x}<span class="muted"> · ${y}</span></button>`).join('')}</div></div>`:''}<div class="grid stats-grid">${[['Acquisition opportunities',bs.length,'Illustrative listings','⌕'],['Estimated market value',money(inv,true),'Across sample marketplace','↗'],['Active evaluations',state.evaluations.length,'Your saved assessments','◈'],['Average health score',`${avg}/100`,'Across sample listings','◎'],['Maintenance alerts',risk,'From sample sensor thresholds','⚙']].map(([l,v,s,i])=>`<div class="card stat-card"><span class="stat-icon">${i}</span><div class="label">${l}</div><div class="value">${v}</div><div class="sub">${s}</div></div>`).join('')}</div><div class="grid two-col"><div class="card chart-card">${cardTitle('Revenue & operating costs','Illustrative sample portfolio · ₹ lakh per month','<div class="chart-legend"><span><i class="legend-dot" style="background:#62d0d2"></i>Revenue</span><span><i class="legend-dot" style="background:#7e9bff"></i>Costs</span></div>')}${chartSvg(DATA.revenue,DATA.expense)}</div><div class="card">${cardTitle('Intelligence brief','Contextual observations from your workspace')}<div>${insights.map((x,i)=>`<div class="insight"><div class="insight-title"><span class="insight-mark">${['↗','◉','⚙'][i]}</span>${['Market fit','Your shortlist','Operations'][i]}</div><p>${x}</p></div>`).join('')}<p class="footnote">Rules-based demo observations. No live market, financial or sensor feeds are connected.</p></div></div></div><div class="grid two-col" style="margin-top:14px"><div class="card">${cardTitle('Opportunities to explore','Selected sample listings · ranked by health','<button class="tiny-link" data-page="marketplace">View marketplace →</button>')}<div class="table-wrap"><table><thead><tr><th>BUSINESS</th><th>ASKING</th><th>MONTHLY PROFIT</th><th>HEALTH</th><th></th></tr></thead><tbody>${[...bs].sort((a,b)=>b.health-a.health).slice(0,4).map(b=>`<tr><td><div class="business-cell"><div class="business-icon">${b.icon}</div><div><strong>${esc(b.name)}</strong><small>${b.category} · ${b.city}</small></div></div></td><td>${money(b.price)}</td><td class="green">${money(profit(b))}</td><td><span class="pill ${b.health<70?'red':b.health<78?'amber':''}">${b.health}/100</span></td><td><button class="tiny-link" data-openbiz="${b.id}">Details</button></td></tr>`).join('')}</tbody></table></div></div><div class="card">${cardTitle('Asset watch','Predictive maintenance · simulated readings','<button class="tiny-link" data-page="maintenance">View assets →</button>')}${state.equipment.slice(0,3).map(e=>`<div class="equipment"><div class="equipment-info"><div class="business-icon">⚙</div><div><strong>${esc(e.name)} <span class="muted">${e.id}</span></strong><small>${esc(e.next)} · ${e.health}% health</small></div></div><span class="pill ${e.risk==='High'?'red':e.risk==='Medium'?'amber':''}">${e.risk}</span></div>`).join('')}</div></div>`}
function marketplace(){let bs=allBusinesses().filter(b=>(!marketFilters.search||`${b.name} ${b.city} ${b.category}`.toLowerCase().includes(marketFilters.search.toLowerCase()))&&(marketFilters.city==='All cities'||b.city===marketFilters.city)&&(marketFilters.category==='All categories'||b.category===marketFilters.category)&&b.price<=marketFilters.budget);if(marketFilters.sort==='Price: low to high')bs.sort((a,b)=>a.price-b.price);else if(marketFilters.sort==='Estimated ROI')bs.sort((a,b)=>roi(b)-roi(a));else bs.sort((a,b)=>b.health-a.health);return `${head('Business marketplace','Find an operating business that fits your investment plan.','<button class="btn" data-page="matching">⌘ Match my profile</button><button class="btn primary" data-page="compare">Compare selected ('+state.compare.length+')</button>')}<div class="filters"><input id="market-search" value="${esc(marketFilters.search)}" placeholder="⌕ Search business, city, category…"><select id="market-city"><option>All cities</option>${[...new Set(allBusinesses().map(b=>b.city))].map(x=>`<option ${marketFilters.city===x?'selected':''}>${x}</option>`).join('')}</select><select id="market-category"><option>All categories</option>${['Retail','Grocery','Restaurant','Cafe','Manufacturing','Warehouse','Automobile','Healthcare','Education'].map(x=>`<option ${marketFilters.category===x?'selected':''}>${x}</option>`).join('')}</select><select id="market-budget">${[['Any budget',Infinity],[ 'Under ₹30L',3000000],['Under ₹50L',5000000],['Under ₹1Cr',10000000]].map(([l,v])=>`<option value="${v}" ${marketFilters.budget===v?'selected':''}>${l}</option>`).join('')}</select><select id="market-sort">${['Recommended','Price: low to high','Estimated ROI'].map(x=>`<option ${marketFilters.sort===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn small" id="clear-filters">Reset</button></div><p class="muted" style="margin:0 0 12px">${bs.length} illustrative opportunities · Representative photos; listing figures are sample estimates.</p><div class="grid listing-grid">${bs.length?bs.map(listingCard).join(''):`<div class="card empty full"><strong>No matching businesses</strong>Adjust your filters to broaden your search.</div>`}</div>`}
function businessPhoto(b){const photos={Grocery:'grocery',Cafe:'cafe',Manufacturing:'manufacturing',Retail:'retail',Automobile:'automobile',Warehouse:'warehouse',Healthcare:'healthcare',Education:'education',Restaurant:'restaurant'};return `assets/marketplace/${photos[b.category]||'retail'}.jpg`}
function listingCard(b){return `<article class="card listing"><div class="listing-top"><img class="listing-photo" src="${businessPhoto(b)}" alt="Representative ${esc(b.category)} business photography" loading="lazy"><div class="listing-photo-shade"></div><div class="listing-top-content"><span class="image-caption">REPRESENTATIVE PHOTO</span><div class="listing-top-badges"><span class="pill ${b.risk==='High'?'red':b.risk==='Medium'?'amber':''}">${b.risk} risk</span><button class="icon-btn listing-save" data-save="${b.id}" title="${state.saved.includes(b.id)?'Remove from saved':'Save business'}" aria-label="${state.saved.includes(b.id)?'Remove from saved':'Save business'}">${state.saved.includes(b.id)?'♥':'♡'}</button></div></div></div><div class="listing-body"><h3>${esc(b.name)}</h3><div class="muted">${b.category} · ${b.area}, ${b.city}</div><div class="price">${money(b.price)}</div><div class="muted">Seller asking price</div><div class="metric-row"><span>Monthly revenue</span><strong>${money(b.revenue)}</strong></div><div class="metric-row"><span>Est. monthly profit</span><strong class="green">${money(profit(b))}</strong></div><div class="metric-row"><span>Indicative annual ROI</span><strong>${roi(b).toFixed(1)}%</strong></div><div class="metric-row"><span>Operating history</span><strong>${b.years} years</strong></div><div class="listing-actions"><button class="btn small" data-openbiz="${b.id}">View profile</button><button class="btn small primary" data-eval="${b.id}">Evaluate</button><button class="btn small" data-compare="${b.id}" title="Add to compare">⇄</button></div></div></article>`}
function estimator(){let e=state.estimator,setup=estimate(e),acq=acquisitionEstimate(state.acq);return `${head('Cost estimator','Transparent, editable estimates for a new venture or an acquisition.','<button class="btn" id="download-estimate">↓ Download estimate</button>')}<div class="scenario-tabs" style="margin-bottom:14px"><button class="${estimateView==='new'?'active':''}" data-estview="new">New business setup</button><button class="${estimateView==='acquisition'?'active':''}" data-estview="acquisition">Existing business acquisition</button></div>${estimateView==='new'?`<div class="grid two-col"><div class="card">${cardTitle('Business assumptions','Adjust any input to recalculate immediately')}<div class="field-grid"><div class="field"><label>Business category</label><select data-est="category">${['Cafe','Retail','Grocery','Restaurant','Manufacturing','Warehouse','Automobile','Healthcare','Education'].map(x=>`<option ${e.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>City</label><select data-est="city">${['Jaipur','Delhi','Gurugram','Noida','Mumbai','Bengaluru','Pune','Faridabad'].map(x=>`<option ${e.city===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Business size</label><select data-est="size">${['Small','Medium','Large'].map(x=>`<option ${e.size===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Commercial area (sq ft)</label><input type="number" min="100" data-est="area" value="${e.area}"></div><div class="field"><label>Monthly rent (₹)</label><input type="number" min="0" data-est="rent" value="${e.rent}"></div><div class="field"><label>Employees</label><input type="number" min="0" data-est="employees" value="${e.employees}"></div><div class="field"><label>Equipment & fit-out (₹)</label><input type="number" min="0" data-est="equipment" value="${e.equipment}"></div><div class="field"><label>Initial inventory (₹)</label><input type="number" min="0" data-est="inventory" value="${e.inventory}"></div><div class="field"><label>Interior & renovation (₹)</label><input type="number" min="0" data-est="interior" value="${e.interior}"></div><div class="field"><label>Licences & registrations (₹)</label><input type="number" min="0" data-est="licences" value="${e.licences}"></div><div class="field"><label>Launch marketing (₹)</label><input type="number" min="0" data-est="marketing" value="${e.marketing}"></div><div class="field"><label>Working capital (months)</label><input type="number" min="1" max="24" data-est="months" value="${e.months}"></div></div><div class="notice" style="margin-top:14px">Illustrative rule-based estimate. Values are assumptions for planning and are not quotes, valuations or financial advice.</div></div><div class="card">${cardTitle('Estimated investment','Range reflects uncertainty in early-stage planning')}<div class="result-hero"><small>RECOMMENDED CAPITAL</small><strong>${money(setup.recommended)}</strong><span>Indicative range ${money(setup.minimum)} – ${money(setup.maximum)}</span></div><div class="spacer"></div>${[['Security deposit',setup.deposit],['Equipment',num(e.equipment)],['Interior & infrastructure',num(e.interior)],['Initial inventory',num(e.inventory)],['Licences & registrations',num(e.licences)],['Technology & software',setup.tech],['Launch marketing',num(e.marketing)],['Working capital',setup.working],['Emergency reserve',setup.reserve]].map(([l,v])=>`<div class="result-line"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="spacer"></div><div class="split"><div><div class="muted">Monthly operating cost</div><strong>${money(setup.opEx)}</strong></div><div><div class="muted">Illustrative monthly revenue</div><strong>${money(setup.revenue)}</strong></div><div><div class="muted">Estimated monthly profit</div><strong class="green">${money(setup.monthProfit)}</strong></div><div><div class="muted">Indicative break-even</div><strong>${setup.breakEven} months</strong></div></div><div class="spacer"></div><button class="btn primary" data-page="financial-studio">Open financial studio →</button></div></div>`:`<div class="grid two-col"><div class="card">${cardTitle('Acquisition assumptions','Seller asking price and estimated value are separate')}<div class="field-grid"><div class="field full"><label>Choose a marketplace listing</label><select id="acq-business"><option value="">Manual entry</option>${allBusinesses().map(b=>`<option value="${b.id}" ${state.acq.business===b.id?'selected':''}>${esc(b.name)} · ${money(b.price)}</option>`).join('')}</select></div>${[['price','Seller asking price (₹)'],['inventory','Inventory valuation (₹)'],['liabilities','Known liabilities (₹)'],['upgrade','Renovation & upgrades (₹)'],['months','Initial operating capital (months)']].map(([k,l])=>`<div class="field"><label>${l}</label><input type="number" min="0" data-acq="${k}" value="${state.acq[k]}"></div>`).join('')}</div><div class="notice" style="margin-top:14px">The fair value band is a simplified planning range using illustrative earnings and asset assumptions. It is not a formal business valuation.</div></div><div class="card">${cardTitle('Acquisition funding view','Goodwill and transaction costs are estimated components')}<div class="result-hero"><small>TOTAL ACQUISITION INVESTMENT</small><strong>${money(acq.total)}</strong><span>Estimated fair value ${money(acq.low)} – ${money(acq.high)}</span></div><div class="spacer"></div>${[['Seller asking price',num(state.acq.price)],['Estimated asset value',acq.assets],['Inventory',num(state.acq.inventory)],['Goodwill estimate',acq.goodwill],['Less known liabilities',-num(state.acq.liabilities)],['Transaction expenses',acq.transaction],['Renovation & upgrades',num(state.acq.upgrade)],['Initial operating capital',acq.working]].map(([l,v])=>`<div class="result-line"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="spacer"></div><p class="footnote">Contributing factors include asking price, stated inventory, operating history and simplified earnings multiple. Confirm all inputs through independent diligence.</p></div></div>`}`}
function estimate(e){let cat={Cafe:1,Restaurant:1.35,Retail:.92,Grocery:1.05,Manufacturing:2.1,Warehouse:1.4,Automobile:1.3,Healthcare:1.25,Education:.88}[e.category]||1,city={Mumbai:1.42,Bengaluru:1.21,Delhi:1.18,Gurugram:1.14,Noida:1.08,Pune:1.12,Jaipur:.92,Faridabad:.91}[e.city]||1;let deposit=e.rent*6,tech=cat*85000,opEx=e.rent+e.employees*18500+e.rent*.42+35000,working=opEx*e.months,recommended=deposit+Number(e.equipment)+Number(e.inventory)+Number(e.interior)+Number(e.licences)+tech+Number(e.marketing)+working,revenue=(e.employees*97000+e.area*350)*cat*city,monthProfit=revenue-opEx,breakEven=Math.max(1,Math.ceil(recommended/Math.max(1,monthProfit)));return{deposit,tech,opEx,working,reserve:recommended*.1,recommended:recommended*1.1,minimum:recommended*.85,maximum:recommended*1.3,revenue,monthProfit,breakEven}}
function acquisitionEstimate(a){let b=a.business&&findBiz(a.business),ask=num(a.price),rev=b?.revenue||ask*.22,earn=b?profit(b):Math.max(1,rev*.22),assets=(b?.price||ask)*.3,goodwill=Math.max(0,earn*24-assets),transaction=ask*.035,working=(b?.expenses||rev*.7)*num(a.months),total=ask+num(a.inventory)-num(a.liabilities)+transaction+num(a.upgrade)+working;return{assets,goodwill,transaction,working,total,low:Math.max(assets+num(a.inventory),earn*18),high:Math.max(assets+num(a.inventory),earn*36)}}
function financialStudio(){return `${head('Financial studio','Plan capital, debt and operating economics with live calculations.','<button class="btn" id="export-finance">Export CSV</button>')}<div class="grid two-col"><div class="card">${cardTitle('Loan calculator','Reducing balance monthly EMI')}<div class="field-grid"><div class="field"><label>Loan amount (₹)</label><input id="loan-amount" type="number" value="2500000" min="0"></div><div class="field"><label>Annual interest (%)</label><input id="loan-rate" type="number" value="11.5" step="0.1" min="0"></div><div class="field"><label>Tenure (years)</label><input id="loan-years" type="number" value="5" min="1" max="30"></div><div class="field"><label>Down payment (₹)</label><input id="loan-down" type="number" value="500000" min="0"></div></div><div id="loan-result" class="spacer"></div></div><div class="card">${cardTitle('Funding planner','Compare project capital with available funding')}<div class="field-grid"><div class="field"><label>Total project cost (₹)</label><input id="fund-cost" type="number" value="5800000"></div><div class="field"><label>Personal capital (₹)</label><input id="fund-personal" type="number" value="2200000"></div></div><div id="fund-result" class="spacer"></div></div><div class="card">${cardTitle('Cash flow planner','Monthly operating projection')}<div class="field-grid">${[['cf-rev','Revenue',900000],['cf-fixed','Fixed costs',190000],['cf-variable','Variable costs',300000],['cf-salary','Salaries',220000],['cf-rent','Rent',80000],['cf-loan','Loan repayment',55000]].map(([id,l,v])=>`<div class="field"><label>${l} (₹)</label><input id="${id}" type="number" value="${v}"></div>`).join('')}</div><div id="cf-result" class="spacer"></div></div><div class="card">${cardTitle('Break-even calculator','Contribution margin method')}<div class="field-grid">${[['be-fixed','Monthly fixed costs',300000],['be-variable','Variable cost per unit',240],['be-price','Selling price per unit',600]].map(([id,l,v])=>`<div class="field"><label>${l} (₹)</label><input id="${id}" type="number" value="${v}"></div>`).join('')}</div><div id="be-result" class="spacer"></div></div><div class="card">${cardTitle('ROI & payback','Simple annual return on initial investment')}<div class="field-grid"><div class="field"><label>Initial investment (₹)</label><input id="roi-invest" type="number" value="4800000"></div><div class="field"><label>Annual net profit (₹)</label><input id="roi-profit" type="number" value="1740000"></div></div><div id="roi-result" class="spacer"></div></div><div class="card">${cardTitle('Funding allocation','Illustrative planning split')}<div class="result-line"><span>Owner capital (40%)</span><strong>Equity contribution</strong></div><div class="result-line"><span>Term loan (35%)</span><strong>Equipment / fit-out</strong></div><div class="result-line"><span>Working capital (20%)</span><strong>Operating buffer</strong></div><div class="result-line"><span>Contingency (5%)</span><strong>Unexpected costs</strong></div><p class="footnote">Suggested allocation is a planning heuristic only. Actual funding eligibility and terms vary.</p></div></div>`}
function maintenance(){let eq=state.equipment;return `${head('Predictive maintenance','Threshold-based equipment monitoring for operating businesses.','<button class="btn" data-action="add-equipment">+ Add equipment</button>')}<div class="notice" style="margin-bottom:14px">SIMULATED SENSOR DATA · Readings and trend charts are seeded demonstration values, not live IoT telemetry. Prediction rules flag higher temperatures, vibration above 7 mm/s, and low health scores.</div><div class="grid stats-grid" style="grid-template-columns:repeat(4,1fr)">${[['Assets monitored',eq.length],['Require attention',eq.filter(e=>e.health<75).length],['Estimated repair exposure',money(eq.reduce((a,e)=>a+(e.health<75?e.repair:0),0))],['Critical risk',eq.filter(e=>e.health<65).length]].map(([a,b])=>`<div class="card stat-card"><div class="label">${a}</div><div class="value">${b}</div><div class="sub">Illustrative equipment data</div></div>`).join('')}</div><div class="grid two-col"><div class="card">${cardTitle('Equipment health','Current condition from demo readings',`<span class="pill amber">${eq.filter(e=>e.health<75).length} need review</span>`)}${eq.map(e=>`<div class="equipment"><div class="equipment-info"><div class="business-icon">⚙</div><div><strong>${esc(e.name)} <span class="muted">${e.id}</span></strong><small>${e.type} · ${e.hours.toLocaleString()} operating hours · ${e.health}% health</small></div></div><div class="row"><span class="pill ${e.risk==='High'?'red':e.risk==='Medium'?'amber':''}">${e.risk}</span><button class="btn small" data-equipment="${e.id}">Readings</button></div></div>`).join('')}</div><div class="card">${cardTitle('Maintenance rationale','Rule-based explanations')}<div>${eq.filter(e=>e.health<75).map(e=>`<div class="insight"><div class="insight-title"><span class="insight-mark">⚠</span>${esc(e.id)} · ${esc(e.name)}</div><p>${e.vibration>7?`Vibration has risen to ${e.vibration} mm/s, above the 7 mm/s demo threshold. `:''}${e.temp>80?`Operating temperature is ${e.temp}°C, above the 80°C demo threshold. `:''}Current health is ${e.health}/100. Inspect within ${esc(e.next.toLowerCase())}. Estimated repair exposure: ${money(e.repair)}.</p></div>`).join('')||'<div class="empty">No equipment has breached the demo maintenance rules.</div>'}<p class="footnote">The prototype uses static sample history and threshold rules. It does not predict actual failures or use a trained ML model.</p></div></div></div><div class="grid two-col" style="margin-top:14px"><div class="card">${cardTitle('Operating temperature trend','Sample historical readings · latest per asset')}<div class="chart-legend"><span><i class="legend-dot" style="background:#62d0d2"></i>Compressor C-102</span></div>${chartSvg(eq[0]?.history.map(x=>x[2])||[78,80,82,84],null,['Aug 30','Sep 10','Sep 20','Sep 30'])}</div><div class="card">${cardTitle('Vibration trend','Sample readings · mm/s')}<div class="chart-legend"><span><i class="legend-dot" style="background:#62d0d2"></i>Compressor C-102</span></div>${chartSvg(eq[0]?.history.map(x=>x[1])||[7.1,7.6,8,8.4],null,['Aug 30','Sep 10','Sep 20','Sep 30'])}</div></div>`}
function digitalTwin(){let b=findBiz(state.twinBiz)||DATA.businesses[0],base=profit(b),scenarioRev=scenario==='optimistic'?1.1:scenario==='pessimistic'?.85:1,scenarioCost=scenario==='optimistic'?.97:scenario==='pessimistic'?1.05:1,rev=b.revenue*(1+num(state.twinRevenue||0)/100)*scenarioRev,rent=b.rent*(1+num(state.twinRent||0)/100),salary=b.employees*22000*(1+num(state.twinSalary||0)/100),cost=(b.expenses-b.rent-b.employees*22000+rent+salary)*scenarioCost,profitNow=rev-cost,risk=Math.min(95,Math.max(5,35+(base-profitNow)/Math.max(1,base)*50));let pessimistic=base*.62,optimistic=base*1.28;return `${head('Business digital twin','Pressure-test a business plan and see how assumptions change the outlook.','<button class="btn" id="reset-twin">Reset assumptions</button>')}<div class="grid two-col"><div class="card">${cardTitle('Select a business','Financial baseline is illustrative')}<div class="field"><label>Marketplace opportunity</label><select id="twin-business">${allBusinesses().map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)} · ${x.city}</option>`).join('')}</select></div><div class="spacer"></div>${[['Revenue change','twinRevenue',-30,30,'%'],['Rent change','twinRent',-20,40,'%'],['Salary change','twinSalary',-20,30,'%']].map(([l,k,min,max,u])=>`<div style="margin:17px 0"><div class="row" style="justify-content:space-between;margin-bottom:7px"><label class="muted">${l}</label><strong id="${k}-value">${state[k]||0}${u}</strong></div><div class="range-row"><input type="range" min="${min}" max="${max}" value="${state[k]||0}" id="${k}"><span class="range-value">${state[k]||0}${u}</span></div></div>`).join('')}<div class="notice">Adjustments apply to revenue, rent and salary costs. Inventory, financing, tax and capacity effects are excluded from this simplified model.</div></div><div class="card">${cardTitle('Projected monthly performance','Simulated case compared with current listing figures',`<div class="scenario-tabs">${['optimistic','realistic','pessimistic'].map(s=>`<button data-scenario="${s}" class="${scenario===s?'active':''}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</div>`)}<div class="split"><div class="result-hero"><small>${scenario.toUpperCase()} · SIMULATED MONTHLY PROFIT</small><strong class="${profitNow>=0?'':'red-text'}">${money(profitNow)}</strong><span>${profitNow>=0?'Operating profit':'Operating loss'} at current settings</span></div><div class="result-hero"><small>BASELINE MONTHLY PROFIT</small><strong>${money(base)}</strong><span>${esc(b.name)} current listing</span></div></div><div class="spacer"></div>${[['Estimated monthly revenue',rev],['Estimated monthly costs',cost],['Profit change',profitNow-base],['Annualized ROI',profitNow*12/b.price*100],['Break-even on asking price',profitNow>0?Math.ceil(b.price/profitNow)+' months':'Not reached at this run rate'],['Indicative risk score',Math.round(risk)+'/100']].map(([l,v])=>`<div class="result-line"><span>${l}</span><strong>${typeof v==='number'&&l.includes('ROI')?v.toFixed(1)+'%':typeof v==='number'?money(v):v}</strong></div>`).join('')}<div class="spacer"></div>${bars([pessimistic,base,optimistic].map(x=>Math.max(0,x)),['Pessimistic','Current','Optimistic'])}<p class="footnote">Scenario cases adjust the selected case revenue (+10% optimistic, −15% pessimistic) and operating costs (−3%, +5%). They are illustrative, not forecasts.</p></div></div>`}
function risk(){let b=findBiz(state.riskBiz)||DATA.businesses[0],score=Math.max(0,100-Math.round((b.risk==='High'?42:b.risk==='Medium'?24:12)+(b.years<4?8:0)+(b.price>b.revenue*6?12:0)));let factors=[['Financial resilience',Math.min(100,Math.round(100-profit(b)/b.revenue*55)),'Operating margin proxy from stated sample revenue and costs.'],['Operational continuity',Math.max(20,100-b.employees*2),'Headcount proxy; staffing records and supplier concentration are not supplied.'],['Location exposure',b.city==='Mumbai'?62:78,'No live rent index, footfall or local competition data is connected.'],['Revenue stability',Math.max(30,95-b.years*2),'Operating history is used as a simple proxy; audited trends are unavailable.'],['Equipment condition',b.category==='Manufacturing'||b.category==='Automobile'?68:82,'Sample listing-level indicator; equipment inspection is required.'],['Debt & liabilities',72,'Liabilities have not been independently verified.']];return `${head('Business risk assessment','Screen opportunities for follow-up using transparent, illustrative indicators.')}<div class="grid two-col"><div class="card">${cardTitle('Select a business','Score reflects available demo listing fields')}<div class="field"><label>Opportunity</label><select id="risk-business">${allBusinesses().map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)} · ${x.city}</option>`).join('')}</select></div><div class="spacer"></div><div class="result-hero"><small>ILLUSTRATIVE HEALTH SCORE</small><strong>${score}<span style="font-size:14px"> / 100</span></strong><span>${score>75?'Fewer immediate screening signals':score>55?'Further review recommended':'Several areas require follow-up'}</span></div><div class="spacer"></div>${factors.map(([l,v,why])=>`<div style="margin:12px 0"><div class="row" style="justify-content:space-between;margin-bottom:7px"><span style="font-size:10px">${l}</span><strong class="${v<60?'red-text':v<75?'amber-text':'green'}">${v}/100</strong></div><div class="progress"><i style="width:${v}%;background:${v<60?'var(--red)':v<75?'var(--amber)':'var(--green)'}"></i></div><div class="footnote" style="margin-top:5px">${why}</div></div>`).join('')}</div><div class="card">${cardTitle('Follow-up actions','Suggested questions before making a decision')}<div>${[['Financial statements','Request 3 years of P&L, balance sheets and reconciliations.'],['Bank and GST records','Compare reported revenue with source records and GST returns.'],['Lease and location','Confirm remaining lease term, renewal rights and rent escalations.'],['Assets & equipment','Inspect ownership, condition, liens and replacement needs.'],['People and suppliers','Review employment obligations and supplier dependencies.'],['Debt & liabilities','Obtain written disclosure and independent legal/accounting review.']].map(([l,d],i)=>`<div class="insight"><div class="insight-title"><span class="insight-mark">${i<2?'◉':'→'}</span>${l}</div><p>${d}</p></div>`).join('')}<p class="footnote">Scores are screening aids calculated from illustrative listing assumptions. They are not verified financial, legal or credit assessments.</p><button class="btn primary" data-page="due-diligence">Open due diligence →</button></div></div></div>`}
const checks=[['Audited financial statements','Last 3 years; signed and reconciled'],['Bank statements','Match deposits to reported revenue'],['GST returns','Cross-check turnover and tax filings'],['Income tax records','Returns and assessment notices'],['Lease agreement','Term, transfer, deposit and escalation'],['Business licences','Current status and transfer requirements'],['Employee obligations','Contracts, payroll and statutory dues'],['Supplier agreements','Terms, exclusivity and payable balances'],['Equipment ownership','Invoices, liens and maintenance condition'],['Outstanding loans','Lender statements and security interests'],['Pending liabilities','Litigation, tax, vendor and customer claims'],['Inventory records','Ageing, valuation and physical count']];
function dueDiligence(){let statuses=state.dd||{};let counts=['Verified','Pending','Missing','Requires review'].map(s=>[s,checks.filter(([k])=>(statuses[k]||'Pending')===s).length]);return `${head('AI due diligence','Organize acquisition evidence and surface gaps for professional review.','<button class="btn" id="dd-summary">Generate summary</button>')}<div class="notice" style="margin-bottom:14px">Document workflow prototype · Files stay in your browser session and are not legally verified. Sample analysis does not replace independent legal, tax or financial review.</div><div class="grid stats-grid" style="grid-template-columns:repeat(4,1fr)">${counts.map(([s,n])=>`<div class="card stat-card"><div class="label">${s}</div><div class="value">${n}</div><div class="sub">of ${checks.length} checklist items</div></div>`).join('')}</div><div class="grid two-col"><div class="card">${cardTitle('Acquisition checklist','Set the current document review status')}<div>${checks.map(([k,d])=>`<div class="check-row"><div><strong>${k}</strong><small>${d}</small></div><select data-dd="${esc(k)}">${['Pending','Verified','Missing','Requires review'].map(s=>`<option ${(statuses[k]||'Pending')===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')}</div></div><div class="card">${cardTitle('Document workspace','Choose files to stage for review')}<div class="field"><label>Select documents (local browser selection)</label><input type="file" id="dd-files" multiple accept=".pdf,.jpg,.jpeg,.png,.xlsx,.csv,.doc,.docx"></div><div id="file-list" class="spacer muted">No files selected.</div><div class="notice">Selected files are not uploaded or processed by an AI service. Use this area to stage a local diligence checklist; verify documents with qualified advisers.</div><div class="spacer"></div><button class="btn primary" id="dd-summary2">Generate gap summary</button><div id="dd-summary-output"></div></div></div>`}
