const _bindFinance=bindFinance;
bindFinance=function(){_bindFinance();if(page==='financial-studio'){const label=document.querySelector('#loan-amount')?.previousElementSibling;if(label)label.textContent='Project / purchase price (₹)';document.getElementById('loan-down')?.addEventListener('input',calcFinance)}};
const _calcFinance=calcFinance;
calcFinance=function(){_calcFinance();const purchase=num(document.getElementById('loan-amount')?.value),down=num(document.getElementById('loan-down')?.value),principal=Math.max(0,purchase-down),rate=num(document.getElementById('loan-rate')?.value)/1200,months=num(document.getElementById('loan-years')?.value)*12,emi=principal===0?0:rate?principal*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1):principal/months,total=emi*months;const out=document.getElementById('loan-result');if(out)out.innerHTML=`<div class="result-hero"><small>MONTHLY EMI</small><strong>${money(emi)}</strong><span>Financed principal ${money(principal)} · Down payment ${money(down)}<br>Total interest ${money(total-principal)} · Total repayment ${money(total)}</span></div>`};
document.addEventListener('change',e=>{if(e.target?.id==='acq-business'){const id=e.target.value,b=findBiz(id);state.acq.business=id;if(b){state.acq.price=b.price;state.acq.inventory=b.inventory}save();renderPage()}});
