let activeEquipmentId=null;const _equipmentDetails=equipmentDetails;equipmentDetails=function(id){activeEquipmentId=id;_equipmentDetails(id);const e=state.equipment.find(x=>x.id===id),modal=document.querySelector('#overlay .modal');if(e&&modal)modal.querySelector('.modal-head').insertAdjacentHTML('afterend',`<div class="notice">Installed ${esc(e.installed)} · Last service ${esc(e.last)}</div><div class="insight" style="margin:10px 0"><div class="insight-title">Maintenance history</div><p>${e.maintenanceHistory.map(h=>`${esc(h.date)} · ${esc(h.event)}`).join('<br>')}</p></div>`)};
