function updatedDigitalTwin(){let b=findBiz(state.twinBiz)||DATA.businesses[0],base=profit(b),val=k=>num(state[k]||0),adjustments=[['Sales revenue','twinRevenue',-30,30],['Product prices','twinPrice',-20,25],['Customer demand','twinDemand',-30,30],['Rent','twinRent',-20,40],['Employee salaries','twinSalary',-20,30],['Inventory costs','twinInventory',-20,40],['Electricity expenses','twinElectricity',-30,60],['Other operating costs','twinOther',-20,40],['Loan interest rate','twinInterest',-4,8]],scenarioRev=scenario==='optimistic'?1.1:scenario==='pessimistic'?.85:1,scenarioCost=scenario==='optimistic'?.97:scenario==='pessimistic'?1.05:1,rev=b.revenue*(1+val('twinRevenue')/100)*(1+val('twinPrice')/100)*(1+val('twinDemand')/100)*scenarioRev,rent=b.rent*(1+val('twinRent')/100),salary=b.employees*22000*(1+val('twinSalary')/100),inventory=b.expenses*.24*(1+val('twinInventory')/100),electricity=b.expenses*.12*(1+val('twinElectricity')/100),other=Math.max(0,b.expenses-b.rent-b.employees*22000-b.expenses*.36)*(1+val('twinOther')/100),principal=b.price*.4,rate=Math.max(0,11.5+val('twinInterest'))/1200,months=60,loan=rate?principal*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1):principal/months,cost=(rent+salary+inventory+electricity+other+loan)*scenarioCost,profitNow=rev-cost,risk=Math.min(95,Math.max(5,35+(base-profitNow)/Math.max(1,base)*50));return `${head('Business digital twin','Pressure-test a business plan and see how assumptions change the outlook.','<button class="btn" id="reset-twin">Reset assumptions</button>')}<div class="grid two-col"><div class="card">${cardTitle('Select a business','Financial baseline is illustrative')}<div class="field"><label>Marketplace opportunity</label><select id="twin-business">${allBusinesses().map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)} · ${x.city}</option>`).join('')}</select></div>${adjustments.map(([label,key,min,max])=>`<div style="margin:13px 0"><div class="row" style="justify-content:space-between;margin-bottom:5px"><label class="muted">${label}</label><strong>${val(key)}%</strong></div><div class="range-row"><input type="range" data-twin="${key}" min="${min}" max="${max}" value="${val(key)}"><span class="range-value">${val(key)}%</span></div></div>`).join('')}<div class="notice">Interest sensitivity assumes a 5-year term and debt equal to 40% of asking price. Taxes and capacity effects are excluded.</div></div><div class="card">${cardTitle('Projected monthly performance','Scenario case compared with current listing figures',`<div class="scenario-tabs">${['optimistic','realistic','pessimistic'].map(s=>`<button data-scenario="${s}" class="${scenario===s?'active':''}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</div>`)}<div class="split"><div class="result-hero"><small>${scenario.toUpperCase()} · SIMULATED MONTHLY PROFIT</small><strong class="${profitNow>=0?'':'red-text'}">${money(profitNow)}</strong><span>${profitNow>=0?'Operating profit':'Operating loss'} at current settings</span></div><div class="result-hero"><small>BASELINE MONTHLY PROFIT</small><strong>${money(base)}</strong><span>${esc(b.name)} current listing</span></div></div><div class="spacer"></div>${[['Estimated monthly revenue',rev],['Estimated monthly costs incl. financing',cost],['Profit change',profitNow-base],['Annualized ROI',profitNow*12/b.price*100],['Break-even on asking price',profitNow>0?Math.ceil(b.price/profitNow)+' months':'Not reached at this run rate'],['Indicative risk score',Math.round(risk)+'/100']].map(([l,v])=>`<div class="result-line"><span>${l}</span><strong>${typeof v==='number'&&l.includes('ROI')?v.toFixed(1)+'%':typeof v==='number'?money(v):v}</strong></div>`).join('')}<div class="spacer"></div>${bars([base*.62,base,base*1.28].map(x=>Math.max(0,x)),['Pessimistic','Current','Optimistic'])}<p class="footnote">Scenario cases change revenue by +10% or −15% and operating costs by −3% or +5%. These are illustrative, not forecasts.</p></div></div>`}
digitalTwin=updatedDigitalTwin;
function businessCompareHTML(){const bs=state.compare.map(findBiz).filter(Boolean);if(bs.length<2)return '';const metrics=[['Seller asking price',b=>money(b.price)],['Monthly revenue',b=>money(b.revenue)],['Monthly operating costs',b=>money(b.expenses)],['Estimated monthly profit',b=>money(profit(b))],['Simple annual ROI',b=>roi(b).toFixed(1)+'%'],['Operating history',b=>b.years+' years'],['Employees',b=>b.employees],['Health indicator',b=>b.health+'/100'],['Risk band',b=>b.risk],['Location',b=>b.area+', '+b.city]];return `<div class="card" style="margin-bottom:14px">${cardTitle('Business shortlist comparison','Side-by-side comparison of selected sample listings','<button class="tiny-link" id="clear-compare">Clear comparison</button>')}<div class="table-wrap"><table><thead><tr><th>INDICATOR</th>${bs.map(b=>`<th>${esc(b.name)}</th>`).join('')}</tr></thead><tbody>${metrics.map(([label,fn])=>`<tr><td>${label}</td>${bs.map(b=>`<td>${fn(b)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function dashboardActivity(){return `<div class="card" style="margin-top:14px">${cardTitle('Recent activity','Actions saved in this browser')}<div class="grid three-col">${state.activities.length?state.activities.slice(0,6).map(a=>`<div class="insight"><div class="insight-title"><span class="insight-mark">↗</span>${esc(a.text)}</div><p>${esc(a.date)}</p></div>`).join(''):'<div class="muted">No recent activity yet. Save or evaluate a business to get started.</div>'}</div></div>`}
function dashboardRecent(){let recent=state.recent.map(findBiz).filter(Boolean);return `<div class="card" style="margin-top:14px">${cardTitle('Recently viewed','Listings you opened in this browser')}<div class="row" style="flex-wrap:wrap">${recent.length?recent.map(b=>`<button class="btn small" data-openbiz="${b.id}">${esc(b.name)} · ${b.city}</button>`).join(''):'<span class="muted">No recently viewed opportunities yet.</span>'}</div></div>`}
function dashboardAnalytics(){let byCat={};allBusinesses().forEach(b=>byCat[b.category]=(byCat[b.category]||0)+b.price);let cat=Object.entries(byCat).sort((a,b)=>b[1]-a[1]).slice(0,5),max=Math.max(...cat.map(x=>x[1])),risk=['Low','Medium','High'].map(k=>[k,allBusinesses().filter(b=>b.risk===k).length]),schedule=[...state.equipment].sort((a,b)=>a.health-b.health).slice(0,4);return `<div class="grid three-col" style="margin-top:14px"><div class="card">${cardTitle('Investment distribution','Sample listing value by business category')}<div>${cat.map(([k,v])=>`<div style="margin:11px 0"><div class="row" style="justify-content:space-between;margin-bottom:5px"><span class="muted">${esc(k)}</span><strong>${money(v,true)}</strong></div><div class="progress"><i style="width:${v/max*100}%"></i></div></div>`).join('')}</div></div><div class="card">${cardTitle('Risk distribution','Sample marketplace opportunities')}<div>${risk.map(([k,n])=>`<div class="equipment"><span>${k} risk</span><span class="pill ${k==='High'?'red':k==='Medium'?'amber':''}">${n} listings</span></div>`).join('')}<p class="footnote">Risk bands are indicative sample screening labels.</p></div></div><div class="card">${cardTitle('Upcoming maintenance','Priority ordered · simulated sensor rules')}${schedule.map(e=>`<div class="equipment"><div><strong>${esc(e.id)} · ${esc(e.name)}</strong><small class="muted" style="display:block;margin-top:3px">${esc(e.next)}</small></div><span class="pill ${e.risk==='High'?'red':e.risk==='Medium'?'amber':''}">${money(e.repair)}</span></div>`).join('')}</div></div>`}
