let voiceOpen=false,voiceRecognition=null,voiceListening=false;
function voiceWidget(){const old=document.getElementById('voice-assistant');if(old)old.remove();const widget=document.createElement('section');widget.id='voice-assistant';widget.className='voice-assistant'+(voiceOpen?' is-open':'');widget.setAttribute('aria-label','EnterpriseX voice assistant');widget.innerHTML=`${voiceOpen?`<div class="voice-panel"><div class="voice-panel-head"><div><strong>Voice assistant</strong><small>Control your EnterpriseX workspace</small></div><button class="voice-close" type="button" aria-label="Close assistant">×</button></div><div class="voice-status" id="voice-status" aria-live="polite">${voiceListening?'Listening…':'Ready when you are'}</div><div class="voice-transcript" id="voice-transcript">Try “open the marketplace” or “search for cafe”.</div><div class="voice-controls"><button class="voice-listen ${voiceListening?'listening':''}" id="voice-listen" type="button">${voiceListening?'■ Stop listening':'🎙 Start listening'}</button><button class="voice-help-toggle" id="voice-help-toggle" type="button">Commands</button></div><form class="voice-command-form" id="voice-command-form"><input id="voice-command-input" aria-label="Type a command" placeholder="Type a command instead…"><button type="submit" aria-label="Send command">↗</button></form><div class="voice-help" id="voice-help" hidden>Navigate: “open dashboard”, “go to maintenance”, “show financial studio”.<br>Businesses: “search for cafe”, “open Juniper cafe”, “save Northfield Grocers”, “evaluate Torque Auto Care”.<br>Utilities: “turn on dark mode”, “show notifications”, “help”.</div><p class="voice-disclaimer">Voice recognition runs in your browser. Microphone permission may be required.</p></div>`:''}<button class="voice-launcher ${voiceListening?'listening':''}" id="voice-launcher" type="button" aria-label="${voiceOpen?'Close':'Open'} voice assistant" title="Voice assistant">${voiceListening?'■':'🎙'}<span>${voiceOpen?'Close':'Voice'}</span></button></section>`;document.body.append(widget);widget.querySelector('#voice-launcher').onclick=()=>{voiceOpen=!voiceOpen;if(!voiceOpen&&voiceListening)stopVoice();voiceWidget()};widget.querySelector('.voice-close')?.addEventListener('click',()=>{voiceOpen=false;if(voiceListening)stopVoice();voiceWidget()});widget.querySelector('#voice-listen')?.addEventListener('click',()=>voiceListening?stopVoice():startVoice());widget.querySelector('#voice-help-toggle')?.addEventListener('click',()=>{const help=widget.querySelector('#voice-help');help.hidden=!help.hidden});widget.querySelector('#voice-command-form')?.addEventListener('submit',e=>{e.preventDefault();const input=widget.querySelector('#voice-command-input');if(input.value.trim()){runVoiceCommand(input.value.trim());input.value=''}})}
function voiceFeedback(text,say=false){const transcript=document.getElementById('voice-transcript'),status=document.getElementById('voice-status');if(transcript)transcript.textContent=text;if(status)status.textContent='Command complete';if(say&&'speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(text))}}
function voiceNormalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim()}
function voiceBusinessMatch(b,phrase){const wanted=voiceNormalize(phrase).split(' ').filter(x=>x.length>1),haystack=voiceNormalize(`${b.name} ${b.city} ${b.category}`);return wanted.length>0&&wanted.every(word=>haystack.includes(word))}
function runVoiceCommand(raw){const text=raw.toLowerCase().replace(/[.,!?]/g,'').trim();let spoken='';const routeAliases={dashboard:['dashboard','overview','home'],marketplace:['marketplace','business marketplace','opportunities','businesses'],estimator:['cost estimator','estimator','estimate','setup costs','acquisition estimator'], 'digital-twin':['digital twin','simulation','simulator'], 'financial-studio':['financial studio','financial tools','finance','loan calculator'],maintenance:['maintenance','equipment','assets','predictive maintenance'],risk:['risk assessment','risk','business risk'], 'due-diligence':['due diligence','documents','checklist'],locations:['locations','location intelligence'],advisor:['advisor','ai advisor','business advisor'],compare:['startup vs acquire','compare startup and acquisition','comparison'],matching:['opportunity match','matching','recommendations'],reports:['reports','analytics','report'],settings:['settings','profile']};if(/^(help|what can i say|show commands)$/.test(text)){document.getElementById('voice-help').hidden=false;spoken='I can navigate pages, search opportunities, open, save or evaluate a business, switch themes, and show notifications.'}else if((()=>{const m=text.match(/^(?:set|change|adjust) (revenue|sales|rent|salary|salaries) (to|by) (-?\d+) ?(?:percent|%)?$/);if(!m)return false;const key={revenue:'twinRevenue',sales:'twinRevenue',rent:'twinRent',salary:'twinSalary',salaries:'twinSalary'}[m[1]],current=num(state[key]||0),value=m[2]==='by'?current+Number(m[3]):Number(m[3]);state[key]=Math.max(-30,Math.min(60,value));save();go('digital-twin');const slider=document.querySelector(`[data-twin="${key}"]`);if(slider){slider.value=state[key];slider.dispatchEvent(new Event('input',{bubbles:true}))}spoken=`${m[1]} adjustment set to ${state[key]} percent in the digital twin.`;return true})()){ }else if(/dark mode|dark theme/.test(text)){const btn=document.querySelector('.theme-toggle');if(btn&&document.documentElement.dataset.theme!=='dark')btn.click();spoken='Dark mode is on.'}else if(/light mode|light theme/.test(text)){const btn=document.querySelector('.theme-toggle');if(btn&&document.documentElement.dataset.theme!=='light')btn.click();spoken='Light mode is on.'}else if(/notifications|notification center/.test(text)){document.getElementById('notifications')?.click();spoken='Here are your notifications.'}else{const search=text.match(/^(?:search(?: for)?|find)(?: businesses?| opportunities?)?\s+(.+)$/);const open=text.match(/^(?:open|show|view)\s+(?:business\s+)?(.+)$/);const action=text.match(/^(save|bookmark|favorite|favourite|evaluate)\s+(?:business\s+)?(.+)$/);let handled=false;if(search){marketFilters.search=search[1];go('marketplace');const input=document.getElementById('market-search')||document.querySelector('.filters input');if(input)input.value=search[1];spoken=`Showing marketplace results for ${search[1]}.`;handled=true}else if(open){const phrase=open[1].replace(/^the /,'');const route=Object.entries(routeAliases).find(([,aliases])=>aliases.includes(phrase));if(route){go(route[0]);spoken=`Opening ${pageNames[route[0]]}.`;handled=true}else{const b=allBusinesses().find(x=>voiceBusinessMatch(x,phrase));if(b){openBusiness(b.id);spoken=`Opening ${b.name}.`;handled=true}}}else if(action){const [,verb,phrase]=action,b=allBusinesses().find(x=>voiceBusinessMatch(x,phrase));if(b){if(verb==='evaluate'){evaluate(b.id);spoken=`Starting an evaluation for ${b.name}.`}else{if(!state.saved.includes(b.id)){state.saved.push(b.id);activity(`Saved ${b.name} using the voice assistant.`);save()}spoken=`${b.name} is saved to your shortlist.`;notify(spoken)}handled=true}}if(!handled){const route=Object.entries(routeAliases).find(([,aliases])=>aliases.some(alias=>text===alias||text===`go to ${alias}`||text===`navigate to ${alias}`));if(route){go(route[0]);spoken=`Opening ${pageNames[route[0]]}.`;handled=true}}if(!handled)spoken='I did not recognize that command. Say “help” to hear supported commands.'}voiceFeedback(spoken,true)}
function startVoice(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){voiceFeedback('Voice recognition is not supported in this browser. You can type a command below.');return}try{voiceRecognition=new Recognition();voiceRecognition.lang='en-IN';voiceRecognition.interimResults=true;voiceRecognition.continuous=false;voiceListening=true;voiceWidget();voiceRecognition.onresult=e=>{let final='';let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const word=e.results[i][0].transcript;if(e.results[i].isFinal)final+=word;else interim+=word}const t=document.getElementById('voice-transcript');if(t)t.textContent=final||interim||'Listening…';if(final)runVoiceCommand(final)};voiceRecognition.onerror=e=>{voiceListening=false;voiceWidget();voiceFeedback(e.error==='not-allowed'?'Microphone access was blocked. Allow microphone access in your browser settings, then try again.':`Voice recognition issue: ${e.error}. You can type a command instead.`)};voiceRecognition.onend=()=>{voiceListening=false;voiceWidget()};voiceRecognition.start()}catch{voiceListening=false;voiceWidget();voiceFeedback('Could not start microphone recognition. Check microphone permission and try again.')}}
function stopVoice(){if(voiceRecognition){voiceRecognition.onend=null;try{voiceRecognition.stop()}catch{}voiceRecognition=null}voiceListening=false;voiceWidget()}
const _frameWithVoice=frame;frame=function(){_frameWithVoice();voiceWidget()};
setupRoute();frame();
